tasks.command:
$ErrorActionPreference = 'Stop'
if (Get-Process -Name TaskbarBuddy.Composition -ErrorAction SilentlyContinue) { throw 'Exit the running buddy before this one-shot launch.' }
$buddy = Start-Process -FilePath './artifacts/attach-fix/TaskbarBuddy.Composition.exe' -ArgumentList '--open-copilot' -WorkingDirectory $PWD.Path -PassThru
if (-not $buddy.WaitForInputIdle(10000)) { throw 'Buddy UI did not become ready.' }
Write-Host ('Started buddy PID ' + $buddy.Id + ' with one Copilot launch requested.')

$ErrorActionPreference = 'Stop'
$package = Join-Path $env:LOCALAPPDATA 'copilot/pkg/win32-arm64/1.0.86-2'
$text = [IO.File]::ReadAllText((Join-Path $package 'sea-loader.js'))
foreach ($term in @('async function gh', 'async function yh')) {
    $index = $text.IndexOf($term, [StringComparison]::Ordinal)
    if ($index -lt 0) { throw ('Missing loader function: ' + $term) }
    $excerpt = $text.Substring($index, [Math]::Min(2000, $text.Length - $index))
    for ($chunk = 0; $chunk -lt $excerpt.Length; $chunk += 180) { Write-Output $excerpt.Substring($chunk, [Math]::Min(180, $excerpt.Length - $chunk)) }
}

$ErrorActionPreference = 'Stop'
$outputExe = [IO.Path]::GetFullPath('artifacts/attach-fix/TaskbarBuddy.Composition.exe')
Get-Process -Name TaskbarBuddy.Composition -ErrorAction SilentlyContinue | Where-Object { $_.Path -eq $outputExe } | ForEach-Object {
    Write-Host ('Stopping build-output buddy PID ' + $_.Id)
    $_.Kill()
    if (-not $_.WaitForExit(5000)) { throw 'Buddy did not exit; build cancelled.' }
}
& 'C:\Program Files\dotnet\dotnet.exe' build src/TaskbarBuddy.Composition --no-restore -o artifacts/attach-fix
exit $LASTEXITCODE
